from read_evidence import *
import html,hashlib,datetime
O=R/'viewer';O.mkdir(exist_ok=True)
figs=[]
def add(title,source,lines,caption):
    figs.append({'number':len(figs)+1,'title':title,'source':source,'text':'\n'.join(lines),'caption':caption})
def excerpt(path,pat=None,start=1,end=999999):
    return [f'{i:>5}  {l}' for i,l in enumerate(read(path).splitlines(),1) if start<=i<=end and (pat is None or re.search(pat,l))]
a=json.loads((R/'acquisition.json').read_text());v=json.loads((R/'integrity_verification.json').read_text())
add('Original evidence integrity','Acquisition record and independent SHA-256 verification',[f"File: {a['file']}",f"Size: {a['bytes']:,} bytes",'Download SHA-256:',a['sha256'],'Independent SHA-256:',v['sha256'],f"Match: {v['matches_download']}",f"Download completed: {a['end_utc']}",f"Verified: {v['verified_utc']}"],'Original archive download hash matches an independent full-file SHA-256 calculation before examination.')
summ=json.loads((R/'archive_summary.json').read_text());ext=json.loads((R/'extraction_record.json').read_text())
add('Evidence inventory','Archive inventory and extraction manifest',[f"Archive members: {summ['members']:,}",f"Regular files extracted: {ext['files']:,}",f"Total logical file bytes: {ext['bytes']:,}",'','Largest evidence members:']+[f"{x['size']:>13,}  {x['path']}" for x in summ['largest'][:5]],'The archive inventory separates memory, supplied strings, Linux files, and metadata before targeted examination.')
add('Accounts and privileges','[root]/etc/passwd; [root]/etc/group; [root]/etc/sudoers.d/10-workers-rule',excerpt('[root]/etc/passwd',r'^(root|worker|sshd):')+['']+excerpt('[root]/etc/group',r'^(sudo|worker|users):')+['']+excerpt('[root]/etc/sudoers.d/10-workers-rule'),'The worker account has UID 1000 and a direct passwordless sudo rule. Its empty sudo-group membership does not remove the separate grant.')
J=json.loads((R/'analysis/journal_events.json').read_text())
def je(select):
    return [f"{e['ts']}  {e.get('message','')}\n  {Path(e['source']).name} record {e['record']}" for e in sorted(J,key=lambda x:x['ts']) if select(e)]
add('Worker authentication and collection session','Parsed system.journal and user-1000.journal',je(lambda e:(Path(e['source']).name=='system.journal' and e['record'] in [879,916,956,959]) or (Path(e['source']).name=='user-1000.journal' and e['record']==129)),'Distinct worker SSH sessions include the later port-58910 session whose process tree launches UAC. Do not automatically classify it as attacker access.')
add('Collector process ancestry','live_response/process/ps_auxwwwf.txt',excerpt('live_response/process/ps_auxwwwf.txt',start=116,end=125),'The visible worker SSH session leads through sudo and bash to UAC; this identifies collector-associated privileged activity.')
add('Processes omitted from ps','live_response/process/hidden_pids_for_ps_command.txt; supplied memory_dump/output-sockstat',excerpt('live_response/process/hidden_pids_for_ps_command.txt')+['','Selected supplied memory socket rows:']+excerpt('memory_dump/output-sockstat',r'\t(sh|python3|bash|ssh|top)\t(939|940|941|975|977)\t',start=348,end=362)[::3],'UAC flagged these PIDs as missing from ps. The supplied memory socket output independently lists sh, python3, bash, ssh, and top for the matching IDs; PID 43168 remains uncorroborated.')
add('Dynamic library preload','chkrootkit/etc_ld_so_preload.txt; chkrootkit/stat_etc_ld_so_preload.txt',excerpt('chkrootkit/etc_ld_so_preload.txt')+['']+excerpt('chkrootkit/stat_etc_ld_so_preload.txt'),'The collector records a global preload reference to libymv.so.3. This is corroborated by the SSH daemon memory map.')
add('Suspicious library mapped in SSH daemon','live_response/process/proc/937/maps.txt',excerpt('live_response/process/proc/937/maps.txt',r'libymv'),'PID 937 maps libymv.so.3 in five regions, corroborating active loading of the library during collection.')
with (R/'working/01931.bin').open('rb') as f:
    f.seek(3858882749);b=f.read(1070)
raw=re.findall(rb'[\x20-\x7e\t]{4,}',b)
lines=[x.decode() for x in raw]
add('Commands recovered from raw memory','memory_dump/avml.lime; file byte offset 3858882749 (1,070-byte excerpt)',lines,'Direct raw-memory excerpt shows UID 0/GID 7823, xmrig renamed to top, an SSH configuration alias, a local mining endpoint, and removal of kit. It is an untimed terminal remnant, not a timestamped audit log.')
checks=json.loads((R/'analysis/memory_offset_verification.json').read_text())
selected=[x for x in checks if 'pty.spawn("/bin/bash")' in x['text']]
add('Python shell evidence verified in raw memory','memory_dump/memory-strings.ascii and memory_dump/avml.lime',[f"Offset {x['reported_offset']}: {x['text']}\nExact match in raw capture: {x['matches_raw_dump_at_reported_offset']}" for x in selected[:3]],'Selected Python PTY strings were verified against the raw memory bytes at the offsets reported in the supplied strings file.')
add('Shell socket on TCP port 22','Supplied memory_dump/output-sockstat',excerpt('memory_dump/output-sockstat',start=347,end=356),'The supplied socket table associates the same kernel socket with sshd, sh, python3, and bash on the .35:48411 connection. TCP/22 alone does not prove an authenticated SSH session.')
add('Miner connection and SSH forwarding','Supplied memory_dump/output-sockstat',excerpt('memory_dump/output-sockstat',start=357,end=362),'SSH PID 975 connects to 192.168.5.95:22 and listens on loopback port 3333. Top PID 977 connects to that loopback listener, consistent with the recovered launch command.')
add('Preload failures during an earlier boot','Parsed system@00064dcd6b0507a3-7a3e1e7e0da0f332.journal~',je(lambda e:Path(e['source']).name=='system@00064dcd6b0507a3-7a3e1e7e0da0f332.journal~' and e['record'] in [760,939,952,990]),'The earlier boot logs repeated preload failures because the library was too short. Later mapped-library evidence must be assessed separately from these earlier errors.')
add('Suspicious library metadata and recorded hash','bodyfile/bodyfile.txt; hash_executables/hash_executables.sha1',excerpt('bodyfile/bodyfile.txt',r'/usr/lib/x86_64-linux-gnu/libymv')+['','Bodyfile columns: filename, inode, mode, UID, GID, size, atime, mtime, ctime, birthtime','']+excerpt('hash_executables/hash_executables.sha1',r'/usr/lib/x86_64-linux-gnu/libymv'),'The library has size 24,024 bytes and a collector-recorded SHA-1. Its file contents were not separately collected, so a full-file SHA-256 is not asserted.')
add('Persistence checks: cron and startup files','[root]/etc/crontab; archive member inventory',excerpt('[root]/etc/crontab',start=7,end=8)+excerpt('[root]/etc/crontab',start=18,end=21)+['','Collected user startup files:']+[x['path'] for _,x in records() if re.search(r'\[root\]/(root|home/worker)/\.(bashrc|profile|bash_logout)$',x['path'])]+['','No authorized_keys, .bash_history, or .zsh_history member found.'],'Cron shows standard maintenance jobs. Missing history/key files are collection absences and do not by themselves establish deletion or absence on the source host.')
add('Host time and forensic collection','live_response/system/timedatectl_status.txt; uac.log',excerpt('live_response/system/timedatectl_status.txt')+['']+excerpt('uac.log',start=1,end=3),'The host reports EDT (UTC-04:00); report timelines normalize to UTC. UAC identifies itself as a development version and uses the ir_triage profile plus AVML.')
for fig in figs:
    content=f'''<!doctype html><html><head><meta charset="utf-8"><title>Evidence {fig['number']:02d}</title><style>body{{font-family:Arial,sans-serif;margin:25px;width:1000px;color:#111;background:#fff}}h1{{font-size:24px;margin:0 0 10px}}p{{font-size:14px;overflow-wrap:anywhere}}pre{{font:20px/1.35 Consolas,monospace;white-space:pre-wrap;overflow-wrap:anywhere;background:#f4f5f6;padding:18px;border:1px solid #ccd0d4}}.note{{color:#444;font-size:13px}}</style></head><body><p class="note">CSCI 4344 CAPSTONE - LOCAL EVIDENCE VIEWER - FIGURE {fig['number']:02d}</p><h1>{html.escape(fig['title'])}</h1><p><b>Source:</b> {html.escape(fig['source'])}</p><pre>{html.escape(fig['text'])}</pre><p class="note">Evidence excerpts generated from preserved working files. Line numbers refer to the stated source. This is an analysis view, not a screenshot of the compromised host.</p></body></html>'''
    (O/f"figure{fig['number']:02d}.html").write_text(content,encoding='utf-8')
(R/'analysis/figures.json').write_text(json.dumps(figs,indent=2))
print('Views',len(figs))

